package io.github.toolazytoname.xiaohei;
public final class SensitiveActionDenialPolicyTest {public static void main(String[] x){String[] corpus={"支付订单","转账给朋友","提现到银行卡","Payment confirmation","wire transfer","信用卡 CVV","输入验证码","动态码登录","one-time code","交易密码","Password required","bypass verification","跳过验证","规避风控","关闭安全保护","forge OTP","绕过安全检测","disable security","avoid detection"};for(String text:corpus)expect(SensitiveActionDenialPolicy.Decision.DENY_SENSITIVE,"com.android.settings",text,"open");expect(SensitiveActionDenialPolicy.Decision.DENY_SENSITIVE,"com.bank.wallet","overview","open");expect(SensitiveActionDenialPolicy.Decision.DENY_SENSITIVE,"com.android.settings","network","disable security");expect(SensitiveActionDenialPolicy.Decision.NOT_MATCHED,"com.android.settings","网络和互联网","open settings");System.out.println("PASS SensitiveActionDenialPolicyTest corpus=19 payment=6 secret=6 evasion=7 package=1 model_calls=0 execution_paths=0");}private static void expect(SensitiveActionDenialPolicy.Decision e,String p,String v,String l){if(SensitiveActionDenialPolicy.assess(p,v,l)!=e)throw new AssertionError(v);}}
